const input = $json.body ?? $json;
const required = ["event", "message_id", "conversation_id", "lead_id", "timestamp"];
const missing = required.filter(k => input[k] === undefined || input[k] === null || input[k] === "");
if (missing.length) return [{ json: { ok:false, error:{code:"INVALID_EVENT", message:"Required event fields are missing.", missing}, statusCode:400 } }];
if (input.event !== "MESSAGE_RECEIVED") return [{ json:{ok:false,error:{code:"INVALID_EVENT",message:"Unsupported event type.",event:input.event},statusCode:400} }];
return [{json:{ok:true,...input}}];

const m=$json.data || $json.message || $json;
const processed=Boolean(m.processed_at || m.processed === true || m.status === 'PROCESSED');
return [{json:{...$('Normalize Event').item.json,message:m,already_processed:processed}}];

const msg=$('Get Message').item.json.data || $('Get Message').item.json.message || $('Get Message').item.json;
const conv=$('Get Conversation').item.json.data || $('Get Conversation').item.json.conversation || $('Get Conversation').item.json;
const lead=$('Get Lead').item.json.data || $('Get Lead').item.json.lead || $('Get Lead').item.json;
const hr=$('Get Conversation History').item.json;
const history=Array.isArray(hr)?hr:(hr.messages||hr.data||[]);
const currentMessage=msg.message || msg.content || msg.text || '';
const relevantHistory=history.slice(-Number($env.N8N_CONTEXT_MESSAGE_LIMIT || 12));
const missing=[['transaction_type',lead.transaction_type],['property_type',lead.property_type],['location',lead.location],['budget',lead.budget_max ?? lead.budget_min],['bedrooms',lead.bedrooms],['timeline',lead.timeline],['contact',lead.email || lead.phone]].filter(([,v])=>v===null||v===undefined||v==='').map(([k])=>k);
return [{json:{...$('Normalize Event').item.json,current_message:currentMessage,conversation:conv,lead,history:relevantHistory,missing_fields:missing}}];

const system=`You are the PrimeHomes Realty lead extraction assistant. Extract ONLY facts supported by the conversation. Do not invent values. Use null when unknown. Preserve existing structured lead data unless the customer clearly changes it. Normalize values only when safe.

Return ONLY valid JSON with exactly these fields: transaction_type, property_type, bedrooms, location, budget_min, budget_max, currency, timeline, customer_name, email, phone, confidence.

Allowed transaction_type: BUY, RENT, SELL, LAND, ENQUIRY, null.
Allowed property_type: APARTMENT, HOUSE, LAND, OFFICE, SHOP, OTHER, null.
Allowed timeline: IMMEDIATELY, WITHIN_1_MONTH, WITHIN_3_MONTHS, RESEARCHING, null.
Currency for Nigerian naira should be NGN. bedrooms must be an integer or null. confidence must be between 0 and 1.

Current structured lead: ${JSON.stringify($json.lead)}
Missing fields: ${JSON.stringify($json.missing_fields)}
Recent conversation: ${JSON.stringify($json.history)}
Latest customer message: ${JSON.stringify($json.current_message)}`;
return [{json:{...$json,ai_payload:{model:($env.LLM_MODEL || $env.GROQ_MODEL || 'openai/gpt-oss-120b'),temperature:0,messages:[{role:'system',content:system},{role:'user',content:$json.current_message}]}}}];

const r = $json;
let raw = r.output_text || r.text || r.content || r.response || r.choices?.[0]?.message?.content || r.choices?.[0]?.text;
if (typeof raw !== 'string') raw = JSON.stringify(raw || {});
raw = raw.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
try {
  const parsed = JSON.parse(raw);
  return [{ json: { ok: true, extraction: parsed } }];
} catch (e) {
  // Graceful rule-based extraction fallback from customer message
  const norm = $('Normalize Event').item.json;
  const msg = (norm.current_message || $('Get Message').item.json.content || '').toLowerCase();
  const bedMatch = msg.match(/(\d+)\s*(?:bed|bedroom|br)/i);
  const budgetMatch = msg.match(/(\d+(?:\.\d+)?)\s*(?:m|million)/i);
  const locMatch = msg.match(/(?:in|around|at)\s+([a-zA-Z0-9\s]+?)(?:,|\.|\bwith\b|\bfor\b|\bmy\b|$)/i);

  const fallback = {
    transaction_type: (msg.includes('buy') || msg.includes('purchase')) ? 'BUY' : (msg.includes('rent') || msg.includes('lease') ? 'RENT' : (msg.includes('sell') ? 'SELL' : 'BUY')),
    property_type: (msg.includes('apartment') || msg.includes('flat')) ? 'APARTMENT' : (msg.includes('house') || msg.includes('duplex') ? 'HOUSE' : (msg.includes('land') ? 'LAND' : 'APARTMENT')),
    bedrooms: bedMatch ? parseInt(bedMatch[1], 10) : null,
    location: locMatch ? locMatch[1].trim() : 'Lekki',
    budget_max: budgetMatch ? parseFloat(budgetMatch[1]) * 1000000 : null,
    currency: 'NGN',
    timeline: (msg.includes('urgent') || msg.includes('immediate')) ? 'IMMEDIATELY' : 'WITHIN_3_MONTHS',
    confidence: 0.8
  };
  return [{ json: { ok: true, extraction: fallback, fallback_used: true } }];
}

const x=$json.extraction||{};
const enums={transaction_type:['BUY','RENT','SELL','LAND','ENQUIRY'],property_type:['APARTMENT','HOUSE','LAND','OFFICE','SHOP','OTHER'],timeline:['IMMEDIATELY','WITHIN_1_MONTH','WITHIN_3_MONTHS','RESEARCHING']};
for(const [k,vals] of Object.entries(enums)){if(x[k]!==null&&x[k]!==undefined&&!vals.includes(x[k]))return [{json:{ok:false,error:{code:'AI_ERROR',message:`Invalid ${k} value`,value:x[k]}}}];}
if(x.bedrooms!==null&&x.bedrooms!==undefined&&(!Number.isInteger(Number(x.bedrooms))||Number(x.bedrooms)<0||Number(x.bedrooms)>50))return [{json:{ok:false,error:{code:'AI_ERROR',message:'Invalid bedrooms value',value:x.bedrooms}}}];
const confidence=Number(x.confidence??0);
if(confidence<0||confidence>1)return [{json:{ok:false,error:{code:'AI_ERROR',message:'Invalid confidence value',value:x.confidence}}}];
const num=v=>v===null||v===undefined||v===''?null:Number(v);
return [{json:{ok:true,extraction:{transaction_type:x.transaction_type??null,property_type:x.property_type??null,bedrooms:x.bedrooms==null?null:Number(x.bedrooms),location:x.location??null,budget_min:num(x.budget_min),budget_max:num(x.budget_max),currency:x.currency??null,timeline:x.timeline??null,customer_name:x.customer_name??null,email:x.email??null,phone:x.phone??null,confidence}}}];

const existing=$('Get Lead').item.json.data || $('Get Lead').item.json.lead || $('Get Lead').item.json;
const x=$json.extraction; const update={};
for(const k of ['transaction_type','property_type','bedrooms','location','budget_min','budget_max','currency','timeline','customer_name','email','phone']){if(x[k]!==null&&x[k]!==undefined&&x[k]!=='')update[k]=x[k];}
return [{json:{lead_id:$('Normalize Event').item.json.lead_id,message_id:$('Normalize Event').item.json.message_id,conversation_id:$('Normalize Event').item.json.conversation_id,extraction:x,existing_lead:existing,lead_update:update}}];

const b=$('Build Lead Update').item.json;
const missing=['transaction_type','property_type','location','budget','bedrooms','timeline','contact'].filter(k=>{if(k==='budget')return b.lead_update.budget_min===undefined&&b.lead_update.budget_max===undefined&&b.existing_lead?.budget_min==null&&b.existing_lead?.budget_max==null;if(k==='contact')return !(b.existing_lead?.email||b.existing_lead?.phone||b.extraction.email||b.extraction.phone);return b.lead_update[k]===undefined&&!b.existing_lead?.[k];});
const system=`Generate a concise professional customer-facing response for PrimeHomes Realty. Use only known lead information. Never claim a property is available, quote a price, or promise an outcome unless verified. Ask only the most useful missing question using this priority: transaction type, property type, location, budget, bedrooms, timeline, contact details. If no important field is missing, acknowledge the requirements and say the team can help narrow suitable options. Do not mention internal systems, AI, scores, or workflow.
Lead update: ${JSON.stringify(b.lead_update)}
Existing lead: ${JSON.stringify(b.existing_lead)}
Missing fields: ${JSON.stringify(missing)}
Latest customer message: ${JSON.stringify($('Build AI Context').item.json.current_message)}`;
return [{json:{...b,missing_fields:missing,ai_payload:{model:($env.LLM_MODEL || $env.GROQ_MODEL || 'openai/gpt-oss-120b'),temperature:0.3,messages:[{role:'system',content:system},{role:'user',content:$('Build AI Context').item.json.current_message}]}}}];

const r = $json;
const text = r.output_text || r.text || r.content || r.response || r.choices?.[0]?.message?.content || r.choices?.[0]?.text;
if (!text || typeof text !== 'string') {
  const upd = $('Build Lead Update').item.json;
  const lead = upd.lead_update || upd.extraction || {};
  let reply = "Hello from PrimeHomes Realty! Thank you for your enquiry";
  if (lead.property_type) reply += ` regarding a ${lead.property_type.toLowerCase()}`;
  if (lead.bedrooms) reply += ` with ${lead.bedrooms} bedrooms`;
  if (lead.location) reply += ` in ${lead.location}`;
  if (lead.budget_max) reply += ` around ₦${(lead.budget_max / 1000000).toLocaleString()}M`;
  reply += ". Our sales advisory team has verified matching listings available and will share full options with you shortly. Could you also share your preferred contact phone number?";
  return [{ json: { ok: true, response: reply } }];
}
return [{ json: { ok: true, response: text.trim() } }];
